{
  "compiler": "naga-30.0.0",
  "entry": "main",
  "glsl": "#version 300 es

precision highp float;
precision highp int;


void main() {
    uint id = uint(gl_VertexID);
    vec2 positions[4] = vec2[4](vec2(-1.0, -1.0), vec2(1.0, -1.0), vec2(-1.0, 1.0), vec2(1.0, 1.0));
    gl_Position = vec4(positions[id], 0.0, 1.0);
    gl_Position.yz = vec2(-gl_Position.y, gl_Position.z * 2.0 - gl_Position.w);
    return;
}

",
  "stage": "vertex",
  "textures": {},
  "uniforms": {},
  "wgsl": "// Shared fullscreen image pass. Original implementation in this project.
@vertex
fn main(@builtin(vertex_index) id: u32) -> @builtin(position) vec4f {
  let positions = array<vec2f, 4>(
    vec2f(-1, -1), vec2f(1, -1), vec2f(-1, 1), vec2f(1, 1),
  );
  return vec4f(positions[id], 0, 1);
}
"
}

