    let t = f32(i);
    let weight = exp(-0.5 * t * t / (u.sigma * u.sigma));
    let delta = u.step * t;
    color += (
      textureSampleLevel(image, sampling, uv + delta, 0) +
      textureSampleLevel(image, sampling, uv - delta, 0)
    ) * weight;
    total += 2.0 * weight;
