{
  "compiler": "naga-30.0.0",
  "entry": "fs_main",
  "glsl": "#version 300 es

precision highp float;
precision highp int;

struct Uniforms {
    vec2 u_resolution;
    float u_dpr;
    float u_glOrigin;
    vec2 u_mouse;
    vec2 u_mouseSpring;
    float u_shapeWidth;
    float u_shapeHeight;
    float u_shapeRadius;
    float u_shapeRoundness;
    float u_mergeRate;
    float u_glareAngle;
    float u_shadowExpand;
    float u_shadowFactor;
    vec2 u_shadowPosition;
    float u_bgTextureRatio;
    int u_bgType;
    int u_bgTextureReady;
    int u_showShape1_;
    int u_blurRadius;
    int u_blurEdge;
    vec4 u_tint;
    float u_refThickness;
    float u_refFactor;
    float u_refDispersion;
    float u_refFresnelRange;
