import { type useLevaControls } from '../Controls';
export interface PresetData {
  version: string;
  timestamp: string;
  controls: ReturnType<typeof useLevaControls>['controls'];
}

export function exportPreset(
  controls: ReturnType<typeof useLevaControls>['controls'],
  filename: string = 'liquid-glass-preset.json',
): void {
  const preset: PresetData = {
    version: '1.0.0',
    timestamp: new Date().toISOString(),
    controls: structuredClone(controls),
  };

  const jsonStr = JSON.stringify(preset, null, 2);
  const blob = new Blob([jsonStr], { type: 'application/json' });
  const url = URL.createObjectURL(blob);

  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

export function importPreset(file: File): Promise<PresetData> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const preset = JSON.parse(content) as PresetData;

        if (!preset.version || !preset.controls) {
          reject(new Error('Invalid preset file format'));
          return;
        }

        resolve(preset);
      } catch (err) {
        reject(new Error(`Failed to parse preset file: ${err}`));
      }
    };

    reader.onerror = () => {
      reject(new Error('Failed to read file'));
    };

    reader.readAsText(file);
  });
}

vendor/studio/src/utils/useResizeOberver.source:
type ObserveCb = (rect: DOMRect, target: HTMLElement) => void;

// Global observer
let resizeObserver: ResizeObserver | null = null;
const observed = new WeakMap<Element, ObserveCb[]>();

const onResize: ResizeObserverCallback = (entries) => {
  entries.forEach((entry) => {
    const info = observed.get(entry.target);

    if (info) {
      const cbList = info;
      cbList.forEach((cb) => {
        cb(entry.contentRect as DOMRect, entry.target as HTMLElement);
      });
    }
  });
};

const unobserve = (el: HTMLElement, cb?: ObserveCb) => {
  if (!observed.has(el) || !resizeObserver) {
    return;
  }

  if (!cb) {
    observed.delete(el);
    resizeObserver.unobserve(el);
    return;
  }

  const cbList = observed.get(el)!;
  const cbIdx = cbList.indexOf(cb);
  if (cbIdx > -1) {
    cbList.splice(cbIdx, 1);
  }
  if (!cbList.length) {
    observed.delete(el);
    resizeObserver.unobserve(el);
  }
};

const observe = (el: HTMLElement, cb: ObserveCb) => {
  if (!resizeObserver) {
    resizeObserver = new ResizeObserver(onResize);
  }

  if (!observed.has(el)) {
    observed.set(el, []);
    resizeObserver.observe(el);
  }

  const cbList = observed.get(el)!;
  if (!cbList.includes(cb)) {
    cbList.push(cb);
  }

  return () => {
    unobserve(el, cb);
  };
};

export function useResizeObserver() {
  return {
    observe,
    unobserve,
  };
}

